-- CONFLICT found by test: core-schema limits containers.depth to 1..3 (space, folder, list). Nested folders need more.
-- Space = 1, each folder level +1, list = last. 12 leaves room for a folder limit up to 10.
ALTER TABLE containers DROP CONSTRAINT containers_depth_check;

ALTER TABLE containers ADD CONSTRAINT containers_depth_chk CHECK (depth BETWEEN 1 AND 12);

CREATE OR REPLACE FUNCTION folders_depth_check() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE d int := 1; cur uuid := NEW.parent_folder_id; lim int;
BEGIN
  -- the containers row (made first, same id) must agree about the parent
  IF (SELECT parent_id FROM containers WHERE id = NEW.id) IS DISTINCT FROM COALESCE(NEW.parent_folder_id, NEW.space_id) THEN
    RAISE EXCEPTION 'containers.parent_id disagrees with folders parent';
  END IF;
  IF cur IS NULL THEN RETURN NEW; END IF;
  SELECT COALESCE((settings->>'max_folder_depth')::int, 3) INTO lim FROM workspaces WHERE id = NEW.workspace_id;
  WHILE cur IS NOT NULL LOOP
    d := d + 1;
    IF d > lim THEN RAISE EXCEPTION 'folder depth limit % exceeded', lim; END IF;
    IF cur = NEW.id THEN RAISE EXCEPTION 'folder cycle'; END IF;
    SELECT parent_folder_id INTO cur FROM folders WHERE id = cur;
  END LOOP;
  RETURN NEW;
END $$;

CREATE TRIGGER folders_depth BEFORE INSERT OR UPDATE OF parent_folder_id ON folders
  FOR EACH ROW EXECUTE FUNCTION folders_depth_check();

